const items = $input.all();
const parsedItems = items.map((item) => {
  item.json.data.resultJson = JSON.parse(item.json.data.resultJson);
  return item;
});
return parsedItems;

// Get the output object from the AI Agent
const output = $input.item.json.output;
const separatedImages = [];

// Loop from Image2 to Image7 and create individual items
for (let i = 2; i <= 7; i++) {
  const imageName = `Image${i}`;
  if (output[imageName]) {
    separatedImages.push({
      json: {
        slide: imageName,
        prompt: output[imageName]
      }
    });
  }
}

return separatedImages;

