=mutation CreateInstagramCarousel {
  createPost(
    input: {
      text: "This is a Sample post"
      channelId: "YOUR_BUFFER_CHANNEL_ID"
      schedulingType: automatic
      mode: shareNow
      assets: [
        { image: { url: "{{ $json.resultUrls[0][0] }}" } }
        { image: { url: "{{ $json.resultUrls[0][1] }}" } }
        { image: { url: "{{ $json.resultUrls[0][2] }}" } }
        { image: { url: "{{ $json.resultUrls[0][3] }}" } }
        { image: { url: "{{ $json.resultUrls[0][4] }}" } }
        { image: { url: "{{ $json.resultUrls[0][5] }}" } }
        { image: { url: "{{ $json.resultUrls[0][6] }}" } }
      ]
      metadata: {
        facebook: {
          type: post
        }
      }
    }
  ) {
    ... on PostActionSuccess {
      post {
        id
        text
        dueAt
        assets { id mimeType }
      }
    }
    ... on MutationError {
      message
    }
  }
}

